const D = { energy: .65, density: .55, persist: .82, speed: 1, scale: 1, hue: 300, x: .5, y: .5, style: 'ribbonknot', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const BW = 200, BH = Math.max(96, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1);
  S.dens = new Float32Array(BW * BH); S.chr = new Float32Array(BW * BH); S.zdp = new Float32Array(BW * BH);
  S.bw = BW; S.bh = BH; S.needBurn = true; S.px = 1.1; S.py = 2.1; S.pz = -2.0;
}

// Dadras ODE base constants (dt=0.005 keeps it stable; 0.01 diverges)
const aC = 3.0, dC = 2.0, eC = 9.0, dt = 0.005;

if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1); S.pj = fr(2) * 2 - 1;
  S.px = 1.0 + fr(3) * 0.6; S.py = 1.5 + fr(4) * 1.2; S.pz = -2.0 + fr(5) * 1.5;
  S.needBurn = true;
}

// slow dramaturgical breathing of the coupling constants (tested stable ranges)
const sec = K.section;
let bV = 2.7 + 0.16 * Math.sin(K.t * 0.021) + S.pj * 0.05 + (sec - 3.5) * 0.006;
let cV = 1.7 + 0.14 * Math.sin(K.t * 0.015 + 1.3) + S.pj * 0.04;
bV = Math.max(2.5, Math.min(2.9, bV));
cV = Math.max(1.5, Math.min(1.9, cV));

// burn-in: settle onto the attractor before it contributes
if (S.needBurn) {
  S.needBurn = false;
  let bx = S.px, by = S.py, bz = S.pz;
  for (let s = 0; s < 600; s++) {
    const dx = by - aC * bx + bV * by * bz;
    const dy = cV * by - bx * bz + bz;
    const dz = dC * bx * by - eC * bz;
    bx += dx * dt; by += dy * dt; bz += dz * dt;
  }
  S.px = bx; S.py = by; S.pz = bz;
}

const g = S.g, dens = S.dens, chr = S.chr, zdp = S.zdp;
const styleI = P.style === 'plasma' ? 1 : P.style === 'ember' ? 2 : P.style === 'ice' ? 3 : P.style === 'pencil' ? 4 : 0;

// TWO incommensurate continuous rotations = motion floor (monotonic on K.t, never re-phases at 8s)
const yawR = 0.15 + P.speed * 0.14;
const rollR = 0.101 + P.speed * 0.088;
const yaw = K.t * yawR + A.rms * 0.3 * Math.sin(K.t * 0.6);
const roll = K.t * rollR;
const pit = 0.42 + 0.26 * Math.sin(K.t * 0.033);
const cY = Math.cos(yaw), sY = Math.sin(yaw), cP = Math.cos(pit), sP = Math.sin(pit), cR = Math.cos(roll), sR = Math.sin(roll);

// center + normalize (attractor mean ~1.3,0,0.3, radius up to ~30)
const cx = 1.3, cy = 0.0, cz = 0.3, fit = 0.045;
const view = Math.min(BW, BH) * 0.34 * (0.4 + P.scale * 1.35);
const hbw = BW * 0.5, hbh = BH * 0.5;

// fade the density trail
const decay = 0.70 + P.persist * 0.26;
for (let i = 0, n = BW * BH; i < n; i++) { dens[i] *= decay; chr[i] *= decay; zdp[i] *= decay; }

// integrate Dadras 40k-70k steps/frame, splat bright into fading buffer
let x = S.px, y = S.py, z = S.pz;
const steps = Math.round(40000 + P.density * 30000);
for (let s = 0; s < steps; s++) {
  const dx = y - aC * x + bV * y * z;
  const dy = cV * y - x * z + z;
  const dz = dC * x * y - eC * z;
  x += dx * dt; y += dy * dt; z += dz * dt;
  if (!(x > -1e3 && x < 1e3) || !(y > -1e3 && y < 1e3) || !(z > -1e3 && z < 1e3)) { x = 1.1; y = 2.1; z = -2.0; continue; }
  const spd = Math.min(1, (Math.abs(dx) + Math.abs(dy) + Math.abs(dz)) * 0.06);
  const nx = (x - cx) * fit, ny = (y - cy) * fit, nz = (z - cz) * fit;
  // yaw (Y) -> pitch (X) -> roll (screen)
  const px1 = nx * cY - nz * sY, pz1 = nx * sY + nz * cY;
  const py1 = ny * cP - pz1 * sP, pz2 = ny * sP + pz1 * cP;
  const sx = px1 * cR - py1 * sR, sy = px1 * sR + py1 * cR;
  const bxi = (hbw + sx * view) | 0, byi = (hbh - sy * view) | 0;
  if (bxi >= 0 && bxi < BW && byi >= 0 && byi < BH) {
    const bi = byi * BW + bxi;
    dens[bi] += 1;
    chr[bi] += pz2 * 0.5 + 0.5;   // view depth -> magenta(back) .. cyan(front) ramp
    zdp[bi] += spd;               // local speed -> white-hot accent on fast segments
  }
}
S.px = x; S.py = y; S.pz = z;

const hueBase = (P.hue + S.hoff * 40 + sec * 10) % 360;
const expo = 0.45 + P.energy * 2.4 + P.density * 0.5 + K.intensity * 0.4 + A.bass * 1.3;

g.loadPixels();
const px = g.pixels;
for (let j = 0; j < BH; j++) {
  const cyn = j / BH - 0.5;
  for (let i = 0; i < BW; i++) {
    const bi = j * BW + i;
    const d = dens[bi];
    const dn = 1 - Math.exp(-d * expo * 0.042);         // log-density tone map
    const avgc = d > 0.0001 ? Math.min(1, chr[bi] / d) : 0.5;
    const avgs = d > 0.0001 ? Math.min(1, zdp[bi] / d) : 0;
    const cxn = i / BW - 0.5;
    const vig = Math.exp(-(cxn * cxn + cyn * cyn) * 2.4);
    let r, gg, b;
    if (styleI === 1) { // plasma: electric violet -> lime, high-key
      const lo = [0.55, 0.10, 0.95], hi = [0.55, 1.0, 0.25];
      const br = Math.min(1, dn * 1.15);
      const gnd = 0.05 * vig;
      r = Math.min(1, gnd * 0.8 + (lo[0] + (hi[0] - lo[0]) * avgc) * br + avgs * br * 0.4);
      gg = Math.min(1, gnd * 0.5 + (lo[1] + (hi[1] - lo[1]) * avgc) * br + avgs * br * 0.4);
      b = Math.min(1, gnd * 1.1 + (lo[2] + (hi[2] - lo[2]) * avgc) * br + avgs * br * 0.4);
    } else if (styleI === 2) { // ember: blackbody heat ramp
      const m = Math.min(1, dn * 1.2 + avgs * dn * 0.4);
      r = Math.min(1, m * 2.0);
      gg = Math.min(1, Math.max(0, m * 1.7 - 0.5));
      b = Math.min(1, Math.max(0, m * 3.1 - 2.35));
      const lift = 0.05 * vig; r = Math.min(1, r + lift * 0.9); gg = Math.min(1, gg + lift * 0.28); b = Math.min(1, b + lift * 0.05);
    } else if (styleI === 3) { // ice: deep blue -> white-hot
      const cold = [0.12, 0.34, 0.88], hot = [0.95, 0.99, 1.0];
      const t2 = Math.min(1, dn * (0.6 + avgs * 0.6));
      const gnd = 0.05 * vig;
      r = Math.min(1, gnd * 0.4 + (cold[0] + (hot[0] - cold[0]) * t2) * (0.15 + 0.9 * t2));
      gg = Math.min(1, gnd * 0.6 + (cold[1] + (hot[1] - cold[1]) * t2) * (0.2 + 0.9 * t2));
      b = Math.min(1, gnd * 1.0 + (cold[2] + (hot[2] - cold[2]) * t2) * (0.35 + 0.75 * t2));
    } else if (styleI === 4) { // pencil: graphite knot on toned paper (mono, abstracted)
      const grain = 0.86 + 0.28 * (Math.abs(Math.sin(i * 12.9 + j * 78.2) * 43758.5) % 1);
      const ink = Math.min(1, Math.pow(dn, 0.8) * grain);
      const paper = 0.9 - (1 - vig) * 0.08;
      const tone = paper - ink * 0.85;
      r = tone * 0.99; gg = tone * 0.965; b = tone * 0.9;
    } else { // ribbonknot (default): magenta -> cyan -> white, glowing on deep ground
      const mag = [1.0, 0.10, 0.80], cyn2 = [0.10, 0.92, 1.0];
      const br = Math.min(1, dn * 1.1);
      const wht = Math.min(1, dn * (0.5 + avgs * 0.9));   // fast/bright segments blow toward white
      const gR = 0.05 + 0.05 * vig, gG = 0.03 + 0.03 * vig, gB = 0.08 + 0.10 * vig;
      const cr = mag[0] + (cyn2[0] - mag[0]) * avgc, cg = mag[1] + (cyn2[1] - mag[1]) * avgc, cb = mag[2] + (cyn2[2] - mag[2]) * avgc;
      r = Math.min(1, gR + cr * br + wht * wht * 0.9);
      gg = Math.min(1, gG + cg * br + wht * wht * 0.9);
      b = Math.min(1, gB + cb * br + wht * wht * 0.9);
    }
    const o = 4 * bi;
    px[o] = Math.max(0, Math.min(255, r * 255));
    px[o + 1] = Math.max(0, Math.min(255, gg * 255));
    px[o + 2] = Math.max(0, Math.min(255, b * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// audio-reactive bloom on bass/treble — partial ADD tint, never full-frame flash
if (styleI !== 4 && (A.bass > 0.02 || A.treble > 0.02)) {
  push(); blendMode(ADD); noStroke();
  const glow = (A.bass * 0.5 + A.treble * 0.35) * (0.4 + P.energy * 0.6);
  fill((hueBase + 20) % 360, 40, 100, glow * 20);
  ellipse(P.x * width, P.y * height, width * 0.8, height * 0.8);
  blendMode(BLEND); pop();
}
